<?php

namespace Tests\Unit\EntitySummary;

use App\Models\Lead;
use App\Services\EntitySummary\LeadSummaryService;
use Mockery;
use Tests\TestCase;

/**
 * Rule: a lead summary is only generated automatically when there is none or the stored one is
 * stale. A summary that exists and is current is never regenerated by the page load, however old.
 */
class LeadSummaryAutoGenerationTest extends TestCase
{
    private function service(?array $cached, int $expectedGenerations): LeadSummaryService
    {
        $service = Mockery::mock(LeadSummaryService::class)->makePartial()->shouldAllowMockingProtectedMethods();
        $service->shouldReceive('getCached')->andReturn($cached);
        $service->shouldReceive('generateAndPersist')
            ->times($expectedGenerations)
            ->andReturn(['meta' => ['is_stale' => false], 'summary' => 'new']);

        return $service;
    }

    private function lead(): Lead
    {
        $lead = new Lead();
        $lead->id = 7;

        return $lead;
    }

    public function test_a_current_summary_is_returned_untouched_and_nothing_is_generated(): void
    {
        $cached = ['summary' => 'existing', 'meta' => ['is_stale' => false, 'generated_at' => '2020-01-01T00:00:00Z']];

        $result = $this->service($cached, 0)->regenerate($this->lead(), onlyIfNeeded: true);

        $this->assertSame($cached, $result);
    }

    public function test_an_old_summary_is_not_regenerated_just_because_of_its_age(): void
    {
        $cached = ['summary' => 'existing', 'meta' => ['generated_at' => now()->subYears(2)->toIso8601String()]];

        $this->assertSame($cached, $this->service($cached, 0)->regenerate($this->lead(), onlyIfNeeded: true));
    }

    public function test_a_fallback_summary_that_is_current_is_not_regenerated_automatically(): void
    {
        $cached = ['summary' => 'fallback', 'meta' => ['source' => 'heuristic', 'is_stale' => false]];

        $this->assertSame($cached, $this->service($cached, 0)->regenerate($this->lead(), onlyIfNeeded: true));
    }

    public function test_a_stale_summary_is_regenerated(): void
    {
        $cached = ['summary' => 'old', 'meta' => ['is_stale' => true]];

        $result = $this->service($cached, 1)->regenerate($this->lead(), onlyIfNeeded: true);

        $this->assertSame('new', $result['summary']);
    }

    public function test_a_missing_summary_is_generated(): void
    {
        $result = $this->service(null, 1)->regenerate($this->lead(), onlyIfNeeded: true);

        $this->assertSame('new', $result['summary']);
    }

    public function test_the_regenerate_button_still_regenerates_a_current_summary(): void
    {
        $cached = ['summary' => 'existing', 'meta' => ['is_stale' => false]];

        $result = $this->service($cached, 1)->regenerate($this->lead());

        $this->assertSame('new', $result['summary']);
    }

    public function test_a_summary_finished_by_another_tab_while_waiting_for_the_lock_is_not_generated_again(): void
    {
        $stale = ['summary' => 'old', 'meta' => ['is_stale' => true]];
        $fresh = ['summary' => 'by another tab', 'meta' => ['is_stale' => false]];

        $service = Mockery::mock(LeadSummaryService::class)->makePartial()->shouldAllowMockingProtectedMethods();
        $service->shouldReceive('getCached')->andReturn($stale, $fresh);
        $service->shouldReceive('generateAndPersist')->never();

        $this->assertSame($fresh, $service->regenerate($this->lead(), onlyIfNeeded: true));
    }

    public function test_the_lock_is_released_after_an_auto_run_that_generates_nothing(): void
    {
        $fresh = ['summary' => 'existing', 'meta' => ['is_stale' => false]];
        $stale = ['summary' => 'old', 'meta' => ['is_stale' => true]];

        $service = Mockery::mock(LeadSummaryService::class)->makePartial()->shouldAllowMockingProtectedMethods();
        $service->shouldReceive('getCached')->andReturn($stale, $fresh);
        $service->shouldReceive('generateAndPersist')->never();
        $service->regenerate($this->lead(), onlyIfNeeded: true);

        // A follow-up manual regenerate must be able to take the lock.
        $next = $this->service($fresh, 1);
        $this->assertSame('new', $next->regenerate($this->lead())['summary']);
    }
}
